returns jsonb language sql security definer set search_path=public as $$
select jsonb_build_object(
'ok',true,'version','V54','role',public.app_current_role(),
'tables',jsonb_build_object(
'app_user_roles',to_regclass('public.app_user_roles') is not null,'invoice_imports',to_regclass('public.invoice_imports') is not null,'invoice_groups',to_regclass('public.invoice_groups') is not null,'invoice_lines',to_regclass('public.invoice_lines') is not null,'invoice_order_links',to_regclass('public.invoice_order_links') is not null,'inventory_return_receipts',to_regclass('public.inventory_return_receipts') is not null,'finance_imports',to_regclass('public.finance_imports') is not null,'finance_rows',to_regclass('public.finance_rows') is not null,'misa_order_invoice_imports',to_regclass('public.misa_order_invoice_imports') is not null,'misa_order_invoice_rows',to_regclass('public.misa_order_invoice_rows') is not null),
'v41',jsonb_build_object('invoice_import_order_ref_header',exists(select 1 from information_schema.columns where table_schema='public' and table_name='invoice_imports' and column_name='order_ref_header'),'invoice_import_order_ref_line_count',exists(select 1 from information_schema.columns where table_schema='public' and table_name='invoice_imports' and column_name='order_ref_line_count'),'invoice_line_order_ref',exists(select 1 from information_schema.columns where table_schema='public' and table_name='invoice_lines' and column_name='order_ref'),'invoice_line_order_ref_source',exists(select 1 from information_schema.columns where table_schema='public' and table_name='invoice_lines' and column_name='order_ref_source')),
'v47',jsonb_build_object('stocktake_baseline_date',exists(select 1 from information_schema.columns where table_schema='public' and table_name='inventory_stocktakes' and column_name='baseline_date'),'stocktake_theoretical_qty',exists(select 1 from information_schema.columns where table_schema='public' and table_name='inventory_stocktakes' and column_name='theoretical_qty'),'stocktake_variance_qty',exists(select 1 from information_schema.columns where table_schema='public' and table_name='inventory_stocktakes' and column_name='variance_qty'),'stocktake_variance_value',exists(select 1 from information_schema.columns where table_schema='public' and table_name='inventory_stocktakes' and column_name='variance_value'),'stocktake_reconcile_status',exists(select 1 from information_schema.columns where table_schema='public' and table_name='inventory_stocktakes' and column_name='reconcile_status')),
'v50',jsonb_build_object('invoice_order_links_ready',to_regclass('public.invoice_order_links') is not null),
