'v53',jsonb_build_object('finance_imports_ready',to_regclass('public.finance_imports') is not null,'finance_rows_ready',to_regclass('public.finance_rows') is not null,'finance_begin_rpc',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='begin_finance_import_v53'),'finance_append_rpc',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='append_finance_rows_v53'),'finance_delete_rpc',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='admin_delete_finance_import_v53')),
'v54',jsonb_build_object('misa_imports_ready',to_regclass('public.misa_order_invoice_imports') is not null,'misa_rows_ready',to_regclass('public.misa_order_invoice_rows') is not null,'misa_begin_rpc',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='begin_misa_order_import_v54'),'misa_append_rpc',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='append_misa_order_rows_v54'),'misa_finalize_rpc',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='finalize_misa_order_import_v54')),
'rpcs',jsonb_build_object('app_user_context',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='app_user_context'),'admin_list_user_roles',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='admin_list_user_roles'),'admin_set_user_role',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='admin_set_user_role'),'replace_shift_data',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='replace_shift_data'),'admin_delete_shopee_data',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='admin_delete_shopee_data'),'save_invoice_history',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='save_invoice_history'),'admin_delete_invoice_history',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='admin_delete_invoice_history'),'confirm_inventory_return_v51',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='confirm_inventory_return_v51'),'reverse_inventory_return_v51',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='reverse_inventory_return_v51'),'begin_finance_import_v53',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='begin_finance_import_v53'),'append_finance_rows_v53',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='append_finance_rows_v53'),'admin_delete_finance_import_v53',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='admin_delete_finance_import_v53'),'begin_misa_order_import_v54',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='begin_misa_order_import_v54'),'append_misa_order_rows_v54',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='append_misa_order_rows_v54'),'finalize_misa_order_import_v54',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='finalize_misa_order_import_v54'))
